INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Social Fluency: Halloween Edition 🎃', 'Network After Work - Sacramento Networking Events', 'Founders & Startups', '**Halloween weekend is the MOST social event of the year and it’s a time when strangers expect to talk to each other. Let''s make sure', '**Halloween weekend is the MOST social event of the year and it’s a time when strangers expect to talk to each other. Let''s make sure you''re ready.** What do you have planned? A costume party, a bar crawl, a work event, or maybe you’re handing out candy to the neighbors, whatever you are getting up to, the whole weekend is packed with chances to meet people. Our 60-minute live, virtual workshop gets you warmed up before you walk in the door. **What you''ll walk away with** **The infinite opener More info: https://www.meetup.com/sacramento-network-after-work-business-networking-events/events/316921087/', '2026-10-29T18:00:00-07:00', 'Online event', 'Online event', 'Sacramento', 'CA', '', 38.58, -121.49, 'Network After Work - Sacramento Networking Events', 6, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/sacramento-network-after-work-business-networking-events/events/316921087/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
