INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Deal or No Deal - House Flipping Pitch Sessions', 'San Diego Real Estate Networking, Agents & Investors', 'Real Estate', 'Bring an address, and we''ll crunch the numbers to see if the property is worth flipping, adding an ADU, or holding for cash flow. Join us', 'Bring an address, and we''ll crunch the numbers to see if the property is worth flipping, adding an ADU, or holding for cash flow. Join us for a practical workshop, "Deal or No Deal - House Flipping Pitch Sessions." **Bring an address, and we''ll analyze it live.** We’ll break down the numbers to determine if the property is worth flipping, adding an ADU, or holding for cash flow. We’ll also brainstorm crowdsourced strategies you could use. All real estate agents in San Diego are welcome. This is More info: https://www.meetup.com/san-diego-real-estate-group/events/316683063/', '2026-10-20T12:00:00-07:00', 'CalHomeCo, Realty of America', '4250 Morena Blvd Ste E, San Diego, CA 92117, USA', 'San Diego', 'CA', '92117', 32.816255815832, -117.220411903801, 'San Diego Real Estate Networking, Agents & Investors', 3, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-diego-real-estate-group/events/316683063/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
