INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Real Estate Agent Referral Network - San Diego', 'Real Estate', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/san-diegos-real-estate-investment-and-exchange-forum/events/316782833/', '2026-10-12T17:00:00-07:00', 'Online event', 'Online event', 'San Diego', 'CA', '', 32.72, -117.17, 'Real Estate Agent Referral Network - San Diego', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-diegos-real-estate-investment-and-exchange-forum/events/316782833/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Real Estate Agent Referral Network - San Diego', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/san-diegos-real-estate-investment-and-exchange-forum/events/316694189/', '2026-10-14T07:00:00-07:00', 'Online event', 'Online event', 'San Diego', 'CA', '', 32.72, -117.17, 'Real Estate Agent Referral Network - San Diego', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-diegos-real-estate-investment-and-exchange-forum/events/316694189/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Real Estate Agent Referral Network - San Diego', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/san-diegos-real-estate-investment-and-exchange-forum/events/316695030/', '2026-10-14T08:00:00-07:00', 'Online event', 'Online event', 'San Diego', 'CA', '', 32.72, -117.17, 'Real Estate Agent Referral Network - San Diego', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/san-diegos-real-estate-investment-and-exchange-forum/events/316695030/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
